(25, 7, 'fr', 'Mise à jour d\'expédition pour la commande {{order_number}}', '<div style=\"margin:0;padding:0;background:#eef2f7;font-family:Arial,Helvetica,sans-serif;color:#111827;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#eef2f7;padding:28px 0;\"><tr><td align=\"center\"><table role=\"presentation\" width=\"680\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:680px;max-width:680px;background:#ffffff;border-radius:20px;overflow:hidden;box-shadow:0 18px 40px rgba(15,23,42,0.12);\"><tr><td style=\"padding:0;background:linear-gradient(135deg,#b45309 0%, #111827 100%);\"><div style=\"padding:34px 40px 28px 40px;\"><div style=\"font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:rgba(255,255,255,0.78);font-weight:700;\">Expédition du magasin</div><h1 style=\"margin:14px 0 12px 0;font-size:30px;line-height:1.2;color:#ffffff;font-weight:700;\">Votre envoi est en cours</h1><p style=\"margin:0;font-size:15px;line-height:1.7;color:rgba(255,255,255,0.88);\">À utiliser pour les expéditions, en transit, retards de livraison et mises à jour de suivi.</p></div></td></tr><tr><td style=\"padding:30px 40px 18px 40px;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border:1px solid #e5e7eb;border-radius:16px;background:#f8fafc;padding:0 24px;\"><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Numéro de commande</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Transporteur</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{carrier_name}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Numéro de suivi</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{tracking_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Statut de livraison</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{shipping_status}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Livraison estimée</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{estimated_delivery}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Destination</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{shipping_address}}</td></tr></table></td></tr><tr><td style=\"padding:8px 40px 8px 40px;\"><div style=\"font-size:14px;line-height:1.8;color:#374151;\"><p style=\"margin:0 0 14px 0;\">Détails clés inclus dans ce modèle :</p><ul style=\"padding-left:18px;margin:0;font-size:14px;line-height:1.7;color:#374151;\"><li style=\"margin:0 0 10px 0;\">URL de suivi : {{tracking_url}}</li><li style=\"margin:0 0 10px 0;\">Statut de la commande : {{order_status}}</li><li style=\"margin:0 0 10px 0;\">Email support : {{support_email}}</li></ul></div></td></tr><tr><td style=\"padding:24px 40px 22px 40px;\"><a href=\"{{tracking_url}}\" style=\"display:inline-block;background:#b45309;color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;padding:14px 22px;border-radius:999px;\">Suivre l\'envoi</a></td></tr><tr><td style=\"padding:0 40px 34px 40px;\"><div style=\"padding-top:18px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.8;color:#6b7280;\">Cet email a été généré par {{app_name}}. Si vous avez besoin d\'aide, contactez {{support_email}} ou visitez {{portal_url}}. Copyright {{current_year}} {{app_name}}.</div></td></tr></table></td></tr></table></div>', '2026-10-01 13:17:25', '2026-10-01 13:17:25'),
(26, 7, 'hi', 'ऑर्डर {{order_number}} के लिए शिपिंग अपडेट', '<div style=\"margin:0;padding:0;background:#eef2f7;font-family:Arial,Helvetica,sans-serif;color:#111827;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#eef2f7;padding:28px 0;\"><tr><td align=\"center\"><table role=\"presentation\" width=\"680\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:680px;max-width:680px;background:#ffffff;border-radius:20px;overflow:hidden;box-shadow:0 18px 40px rgba(15,23,42,0.12);\"><tr><td style=\"padding:0;background:linear-gradient(135deg,#b45309 0%, #111827 100%);\"><div style=\"padding:34px 40px 28px 40px;\"><div style=\"font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:rgba(255,255,255,0.78);font-weight:700;\">स्टोरफ्रंट शिपिंग</div><h1 style=\"margin:14px 0 12px 0;font-size:30px;line-height:1.2;color:#ffffff;font-weight:700;\">आपका शिपमेंट आगे बढ़ रहा है</h1><p style=\"margin:0;font-size:15px;line-height:1.7;color:rgba(255,255,255,0.88);\">डिस्पैच, इन-ट्रांजिट, देरी डिलीवरी, और ट्रैकिंग अपडेट के लिए उपयोग करें।</p></div></td></tr><tr><td style=\"padding:30px 40px 18px 40px;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border:1px solid #e5e7eb;border-radius:16px;background:#f8fafc;padding:0 24px;\"><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">ऑर्डर संख्या</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">कैरियर</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{carrier_name}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">ट्रैकिंग नंबर</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{tracking_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">शिपिंग स्थिति</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{shipping_status}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">अनुमानित डिलीवरी</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{estimated_delivery}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">गंतव्य</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{shipping_address}}</td></tr></table></td></tr><tr><td style=\"padding:8px 40px 8px 40px;\"><div style=\"font-size:14px;line-height:1.8;color:#374151;\"><p style=\"margin:0 0 14px 0;\">इस टेम्पलेट में शामिल मुख्य विवरण:</p><ul style=\"padding-left:18px;margin:0;font-size:14px;line-height:1.7;color:#374151;\"><li style=\"margin:0 0 10px 0;\">ट्रैकिंग URL: {{tracking_url}}</li><li style=\"margin:0 0 10px 0;\">ऑर्डर स्थिति: {{order_status}}</li><li style=\"margin:0 0 10px 0;\">सहायता ईमेल: {{support_email}}</li></ul></div></td></tr><tr><td style=\"padding:24px 40px 22px 40px;\"><a href=\"{{tracking_url}}\" style=\"display:inline-block;background:#b45309;color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;padding:14px 22px;border-radius:999px;\">शिपमेंट ट्रैक करें</a></td></tr><tr><td style=\"padding:0 40px 34px 40px;\"><div style=\"padding-top:18px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.8;color:#6b7280;\">यह ईमेल {{app_name}} द्वारा उत्पन्न किया गया था। यदि आपको सहायता चाहिए, तो {{support_email}} से संपर्क करें या {{portal_url}} पर जाएं। कॉपीराइट {{current_year}} {{app_name}}।</div></td></tr></table></td></tr></table></div>', '2026-10-01 13:17:25', '2026-10-01 13:17:25'),
(27, 7, 'en', 'Shipping update for order {{order_number}}', '<div style=\"margin:0;padding:0;background:#eef2f7;font-family:Arial,Helvetica,sans-serif;color:#111827;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#eef2f7;padding:28px 0;\"><tr><td align=\"center\"><table role=\"presentation\" width=\"680\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:680px;max-width:680px;background:#ffffff;border-radius:20px;overflow:hidden;box-shadow:0 18px 40px rgba(15,23,42,0.12);\"><tr><td style=\"padding:0;background:linear-gradient(135deg,#b45309 0%, #111827 100%);\"><div style=\"padding:34px 40px 28px 40px;\"><div style=\"font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:rgba(255,255,255,0.78);font-weight:700;\">Storefront Shipping</div><h1 style=\"margin:14px 0 12px 0;font-size:30px;line-height:1.2;color:#ffffff;font-weight:700;\">Your shipment is moving</h1><p style=\"margin:0;font-size:15px;line-height:1.7;color:rgba(255,255,255,0.88);\">Use for dispatch, in-transit, delayed delivery, and tracking updates.</p></div></td></tr><tr><td style=\"padding:30px 40px 18px 40px;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border:1px solid #e5e7eb;border-radius:16px;background:#f8fafc;padding:0 24px;\"><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Order Number</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Carrier</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{carrier_name}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Tracking Number</td><td style=\"padding:10px 0;border-bottom:1p